 public function rules():array{$workProcess=$this->route('workProcess');$asset=fn(string $a,mixed $v,Closure $fail)=>PublicAssetPath::isSafe(is_string($v)?$v:null)?:$fail('Use an approved local image path.');$safeUrl=fn(string $a,mixed $v,Closure $fail)=>$v&&!PublicLink::isSafeUrl((string)$v)?$fail('Use a safe relative or HTTP/HTTPS URL.'):null;return ['title'=>['required','string','max:160'],'slug'=>['required','max:160','regex:/^[a-z0-9]+(?:-[a-z0-9]+)*$/',Rule::unique(WorkProcess::class)->ignore($workProcess),fn($a,$v,$f)=>in_array($v,WorkProcessRegistry::RESERVED,true)?$f('This slug is reserved.'):null],'eyebrow'=>['nullable','string','max:120'],'short_description'=>['required','string','max:500'],'overview'=>['nullable','string','max:20000'],'icon'=>['nullable',Rule::in(WorkProcessRegistry::ICONS)],'featured_image_path'=>['nullable','string','max:255',$asset],'featured_image_alt'=>['nullable','required_with:featured_image_path','string','max:160'],'hero_style'=>['required',Rule::in(WorkProcessRegistry::HERO_STYLES)],'template'=>['required',Rule::in(WorkProcessRegistry::TEMPLATES)],'is_featured'=>['boolean'],'primary_cta_label'=>['nullable','required_with:primary_cta_url','string','max:80'],'primary_cta_url'=>['nullable','required_with:primary_cta_label','string','max:2048',$safeUrl],'secondary_cta_label'=>['nullable','required_with:secondary_cta_url','string','max:80'],'secondary_cta_url'=>['nullable','required_with:secondary_cta_label','string','max:2048',$safeUrl],'meta_title'=>['nullable','string','max:70'],'meta_description'=>['nullable','string','max:170'],'canonical_url'=>['nullable','url:http,https','max:2048',function($a,$v,$f){$site=WebsiteSetting::value('site_url');if($v&&$site&&strcasecmp((string)parse_url($v,PHP_URL_HOST),(string)parse_url($site,PHP_URL_HOST))!==0)$f('Canonical URL must use the website host.');}],'og_title'=>['nullable','string','max:70'],'og_description'=>['nullable','string','max:200'],'og_image_path'=>['nullable','string','max:25